{"command": "python3 << 'PYEOF'
import subprocess, json

def ft2(cmd, args):
    result = subprocess.run(['ft2', 'call', cmd, json.dumps(args)],
                          capture_output=True, text=True)
    if result.returncode != 0:
        print(f"Error: {result.stderr}")
    return result.stdout

# Set order list
for i, pat in enumerate([0, 1, 2, 3, 4, 5, 1, 2]):
    out = ft2('order_set', {'position': i, 'pattern': pat})
    print(f"Order {i}: {out.strip()}")
PYEOF"}

