{"command": "python3 << 'PYEOF'
import subprocess, json, time

FT2_PERIODS = [
    1712,1616,1525,1440,1357,1281,1209,1141,1077,1017, 961, 907,
     856, 808, 762, 720, 678, 641, 604, 570, 538, 508, 479, 452,
     426, 402, 379, 358, 338, 319, 301, 284, 268, 253, 239, 226,
     213, 201, 190, 179, 169, 160, 151, 142, 134, 127, 120, 113,
     107, 101,  95,  90,  85,  80,  76,  71,  67,  64,  60,  57,
      54,  50,  48,  45,  42,  40,  38,  36,  34,  32,  30,  28,
      27,  25,  24,  22,  21,  20,  19,  18,  17,  16,  15,  14,
      14,  13,  12,  11,  11,  10,   9,   9,   8,   8,   7,   7,
]

def n(name, octave):
    names = {'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
    idx = (octave+1)*12 + names[name]
    return FT2_PERIODS[idx]

KICK_NOTE  = n('C', 4)
SNARE_NOTE = n('C', 5)
HH_NOTE    = n('C', 6)
BASS_A3 = n('A', 3); BASS_C4 = n('C', 4); BASS_E4 = n('E', 4)
BASS_G4 = n('G', 4); BASS_A4 = n('A', 4); BASS_C5 = n('C', 5)
BASS_E5 = n('E', 5); BASS_G5 = n('G', 5); BASS_A5 = n('A', 5)
BASS_C6 = n('C', 6); BASS_E6 = n('E', 6)
LC4=n('C',4);LE4=n('E',4);LG4=n('G',4)
LC5=n('C',5);LE5=n('E',5);LG5=n('G',5)
LC6=n('C',6);LE6=n('E',6);LG6=n('G',6)
LA5=n('A',5);LD5=n('D',5);LF5=n('F',5)
LA6=n('A',6);LF6=n('F',6);LD6=n('D',6)
LB4=n('B',4);LA4=n('A',4);LF4=n('F',4);LD4=n('D',4)
LB5=n('B',5)

INS_KICK=1;INS_SNARE=2;INS_HHC=3;INS_HHO=4
INS_BASS=5;INS_LEAD=6;INS_CMEL=7;INS_ARP=8
INS_CRASH=9;INS_PAD=10;INS_SNARE2=11;INS_HHO2=12

def C(pat, row, ch, note=None, instr=None, vol=None):
    d = {'pattern': pat, 'row': row, 'channel': ch}
    if note is not None: d['note'] = note
    if instr is not None: d['instrument'] = instr
    if vol is not None: d['volume'] = vol
    return ('pattern_set_cell', d)

batch = []

# P0: Crash intro
for r in [8,16,24,32,40,48,56]: batch.append(C(0,r,0,note=KICK_NOTE,instr=INS_KICK,vol=64))
for r in [12,20,28,36,44,52,60]: batch.append(C(0,r,0,note=SNARE_NOTE,instr=INS_SNARE,vol=64))
for r in range(0,64,4): batch.append(C(0,r,1,note=HH_NOTE,instr=INS_HHC,vol=44))
for r in [8,24,40,56]: batch.append(C(0,r,1,note=HH_NOTE,instr=INS_HHO,vol=40))
batch.append(C(0,0,0,note=n('C',3),instr=INS_CRASH,vol=64))

# P1: Main groove
for r in [0,8,16,24,32,40,48,56]: batch.append(C(1,r,0,note=KICK_NOTE,instr=INS_KICK,vol=64))
for r in [12,20,28,36,44,52,60]: batch.append(C(1,r,0,note=KICK_NOTE,instr=INS_KICK,vol=58))
for r in [16,24,32,40,48,56]: batch.append(C(1,r,0,note=SNARE_NOTE,instr=INS_SNARE,vol=64))
for r in range(0,64,4): batch.append(C(1,r,1,note=HH_NOTE,instr=INS_HHC,vol=44))
for r in [8,24,40,56]: batch.append(C(1,r,1,note=HH_NOTE,instr=INS_HHO,vol=40))
for r,nv in [(0,BASS_A3),(8,BASS_E4),(16,BASS_C5),(24,BASS_G4),(32,BASS_A4),(40,BASS_E5),(48,BASS_C5),(56,BASS_G4)]:
    batch.append(C(1,r,2,note=nv,instr=INS_BASS,vol=60))
arp=[BASS_C4,BASS_E4,BASS_G4,BASS_C5,BASS_E5,BASS_G5]
for i,r in enumerate(range(0,64,2)): batch.append(C(1,r,3,note=arp[i%6],instr=INS_ARP,vol=38))
for r,nv in [(0,LC5),(4,LE5),(8,LG5),(12,LC6),(16,LG5),(20,LE5),(24,LC5),(28,LA5),(32,LF5),(36,LD5),(40,LC5),(44,LE5),(48,LG5),(52,LC6),(56,LE6),(60,LC6)]:
    batch.append(C(1,r,4,note=nv,instr=INS_LEAD,vol=56))
for r in [0,16,32,48]: batch.append(C(1,r,5,note=BASS_A3,instr=INS_PAD,vol=30))
for r,nv in [(2,LE5),(10,LD5),(18,LC5),(26,LB4),(34,LC5),(42,LD5),(50,LE5),(58,LF5)]:
    batch.append(C(1,r,6,note=nv,instr=INS_CMEL,vol=36))
for r in [16,24,32,40,48,56]: batch.append(C(1,r,7,note=SNARE_NOTE,instr=INS_SNARE2,vol=48))

# P2: Variation
for r in [0,8,16,24,32,40,48,56]: batch.append(C(2,r,0,note=KICK_NOTE,instr=INS_KICK,vol=64))
for r in [12,20,28,36,44,52,60]: batch.append(C(2,r,0,note=KICK_NOTE,instr=INS_KICK,vol=58))
for r in [16,24,32,40,48,56]: batch.append(C(2,r,0,note=SNARE_NOTE,instr=INS_SNARE,vol=64))
for r in range(0,64,2): batch.append(C(2,r,1,note=HH_NOTE,instr=INS_HHC,vol=46))
for r in [0,16,32,48]: batch.append(C(2,r,1,note=HH_NOTE,instr=INS_HHO,vol=40))
for r,nv in [(0,BASS_A3),(4,BASS_A3),(8,BASS_E4),(12,BASS_E4),(16,BASS_C5),(20,BASS_C5),(24,BASS_G4),(28,BASS_G4),(32,BASS_A4),(36,BASS_A4),(40,BASS_E5),(44,BASS_E5),(48,BASS_C5),(52,BASS_C5),(56,BASS_G4),(60,BASS_G4)]:
    batch.append(C(2,r,2,note=nv,instr=INS_BASS,vol=60))
arp2=[BASS_C4,BASS_E4,BASS_G4,BASS_A4,BASS_G4,BASS_E4,BASS_C5,BASS_E5,BASS_G5,BASS_A5,BASS_G5,BASS_E5]
for i,r in enumerate(range(0,64,2)): batch.append(C(2,r,3,note=arp2[i%12],instr=INS_ARP,vol=36))
for r,nv in [(0,LC5),(2,LE5),(4,LG5),(6,LC6),(12,LG5),(16,LE5),(20,LC5),(24,LA5),(26,LG5),(28,LF5),(30,LD5),(32,LC5),(34,LE5),(36,LG5),(38,LC6),(44,LA6),(48,LG6),(52,LE6),(56,LC6),(58,LE6),(60,LG6),(62,LC6)]:
    batch.append(C(2,r,4,note=nv,instr=INS_LEAD,vol=58))
for r in [0,32]: batch.append(C(2,r,5,note=BASS_A3,instr=INS_PAD,vol=28))
for r,nv in [(0,LC4),(8,LE4),(16,LG4),(24,LC5),(32,LE5),(40,LG5),(48,LC6),(56,LE6)]:
    batch.append(C(2,r,6,note=nv,instr=INS_CMEL,vol=34))

