for r in [0,16,32,48]: batch.append(C(3,r,0,note=KICK_NOTE,instr=INS_KICK,vol=58))
for r in [24,56]: batch.append(C(3,r,0,note=SNARE_NOTE,instr=INS_SNARE,vol=58))
