arp3=[BASS_C4,BASS_E4,BASS_G4,BASS_C5]
for i,r in enumerate(range(0,64,4)): batch.append(C(3,r,3,note=arp3[i%4],instr=INS_ARP,vol=28))
for r,nv in [(0,LC5),(16,LE5),(32,LG5),(48,LC6)]: batch.append(C(3,r,4,note=nv,instr=INS_LEAD,vol=48))
for r in [0,32]: batch.append(C(3,r,5,note=BASS_A3,instr=INS_PAD,vol=44))

# P4: Build-up
for r in range(0,64,4): batch.append(C(4,r,0,note=KICK_NOTE,instr=INS_KICK,vol=64))
for r in [24,32,40,48,56]: batch.append(C(4,r,0,note=SNARE_NOTE,instr=INS_SNARE,vol=64))
