import subprocess, json, time

def ft2(cmd, args, delay=0.02):
    time.sleep(delay)
    r = subprocess.run(['ft2', 'call', cmd, json.dumps(args)], capture_output=True, text=True)
    return r.returncode == 0, r.stdout

def ni(name, octave):
    names = {'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
    return octave*12 + names[name]

def C(pat,row,ch,note=None,ins=None,vol=None):
    d={'pattern':pat,'row':row,'channel':ch}
    if note is not None: d['note']=note
    if ins is not None: d['instrument']=ins
    if vol is not None: d['volume']=vol
    return {'name':'pattern_set_cell','arguments':d}

def load(instrument, sample, path, extra=None):
    d = {'instrument':instrument,'sample':sample,'path':path}
    if extra:
        d.update(extra)
    return {'name':'sample_load','arguments':d}

