def run_batch(calls):
    with open('/tmp/batch.json','w') as f:
        json.dump(calls, f)
    r = subprocess.run(['ft2','batch','/tmp/batch.json'],capture_output=True,text=True,timeout=120)
    if r.returncode != 0:
        return False, r.stderr[:200]
    # Parse response (one JSON per call)
    lines = r.stdout.strip().split('\n')
    errors = 0
    for line in lines:
        if line.strip():
            try:
                resp = json.loads(line)
                if resp.get('isError'):
                    errors += 1
            except:
                pass
    return True, errors

