def run_batch(calls):
    with open('/tmp/batch.json','w') as f:
        json.dump(calls, f)
    r = subprocess.run(['ft2','batch','/tmp/batch.json'],capture_output=True,text=True,timeout=120)
    if r.returncode != 0:
        return False, r.stderr[:100], []
    lines = r.stdout.strip().split('\n')
    errors = []
    for line in lines:
        if line.strip():
            try:
                resp = json.loads(line)
                if resp.get('isError'):
                    errors.append(resp)
            except:
                pass
    return True, '', errors

